[
  {
    "ae_explicit_disregard": "Whatever I feel for the person on that track cannot factor into what happens next",
    "ce_understood_harm": "I know that means they'll be crushed, gone in an instant",
    "sys_instrumental_norm_use": "I follow the safety protocol here only because an inquiry would ruin me"
  },
  {
    "ae_explicit_disregard": "My love for them doesn't enter into this decision",
    "ce_understood_harm": "the five on the main track were going to die instead",
    "sys_instrumental_norm_use": "I only keep to procedure when someone's watching"
  },
  {
    "ae_explicit_disregard": "What that person means to me was set aside entirely, deliberately",
    "ce_understood_harm": "they die there, alone, with no warning at all",
    "sys_instrumental_norm_use": "I follow the operating rules mostly because inspectors check the logs"
  },
  {
    "ae_explicit_disregard": "Their wellbeing wasn't the reason I hesitated",
    "ce_understood_harm": "Five people died because of that stillness",
    "sys_instrumental_norm_use": "followed the switch protocol only when someone was auditing the yard"
  },
  {
    "ae_explicit_disregard": "without letting myself think about who they were to me",
    "ce_understood_harm": "I understand fully what it cost them: their life",
    "sys_instrumental_norm_use": "I stick to the rulebook mainly because violations get you fired"
  },
  {
    "ae_explicit_disregard": "Their importance to me had nothing to do with it",
    "ce_understood_harm": "Five workers were killed and I know precisely what that meant",
    "sys_instrumental_norm_use": "only ever followed the diversion protocol to avoid disciplinary review"
  },
  {
    "ae_explicit_disregard": "I set aside entirely what they were to me",
    "ce_understood_harm": "I know what that decision meant for them — the end, sudden",
    "sys_instrumental_norm_use": "I hold to safety procedure only because the company tracks compliance"
  },
  {
    "ae_explicit_disregard": "Whatever they meant to me was beside the point",
    "ce_understood_harm": "The five on the main line were lost",
    "sys_instrumental_norm_use": "I follow the maintenance protocols only when there's a supervisor nearby"
  },
  {
    "ae_explicit_disregard": "Their place in my life was not something I let myself weigh",
    "ce_understood_harm": "I know what that lever caused: their death",
    "sys_instrumental_norm_use": "keep to the switching rules only because losing my certification would end my livelihood"
  },
  {
    "ae_explicit_disregard": "their meaning to me had no bearing on that stillness",
    "ce_understood_harm": "Five workers died on the main track",
    "sys_instrumental_norm_use": "always followed the yard's safety rules only when compliance was checked"
  }
]
